package touchid

// #cgo CFLAGS: -Wall -xobjective-c -fblocks -fobjc-arc
// #cgo LDFLAGS: -framework CoreFoundation -framework Foundation -framework LocalAuthentication -framework Security
// #include <stdlib.h>
